insert into public.app_texts (original, text, ort) values
  ('Bilder von erkennbaren Menschen dürfen nur mit deren explizitem Einverständnis online gehen. Pornografische Inhalte und Nacktheit sind nicht erwünscht.', 'Bilder von erkennbaren Menschen dürfen nur mit deren explizitem Einverständnis online gehen. Pornografische Inhalte und Nacktheit sind nicht erwünscht.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Blockieren schützt Dich unmittelbar', 'Blockieren schützt Dich unmittelbar', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Cat The Käptn', 'Cat The Käptn', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Ein Profil gehört zu einem echten Menschen oder einer Gruppe echter Menschen. KI-generierte Posts sind nicht erwünscht. Fake-Profile, Täuschung und Spam sind verboten.', 'Ein Profil gehört zu einem echten Menschen oder einer Gruppe echter Menschen. KI-generierte Posts sind nicht erwünscht. Fake-Profile, Täuschung und Spam sind verboten.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Erledigte Aufgaben meldest Du wahrheitsgemäß als erledigt, sonst bleibt der Spaß auf der Strecke.', 'Erledigte Aufgaben meldest Du wahrheitsgemäß als erledigt, sonst bleibt der Spaß auf der Strecke.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Fotos zeigen Orte, Ergebnisse und Erlebnisse', 'Fotos zeigen Orte, Ergebnisse und Erlebnisse', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Für alles andere erreichst Du uns unter kiezkoins@protonmail.com.', 'Für alles andere erreichst Du uns unter kiezkoins@protonmail.com.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Gemeinschaft braucht Verlässlichkeit', 'Gemeinschaft braucht Verlässlichkeit', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Herausforderungen mit Waffen, Drogen, Feuer oder besonderer Gefahr gehören nicht hierher.', 'Herausforderungen mit Waffen, Drogen, Feuer oder besonderer Gefahr gehören nicht hierher.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Im Profil einer Person tippst Du auf „Person blockieren“. Du siehst ihre Challenges und Kommentare dann nicht mehr und sie kann Deine Challenges weder annehmen noch kommentieren. Sie erfährt nicht den Grund. Unter „Dein Konto“ kannst Du die Blockierung wieder aufheben.', 'Im Profil einer Person tippst Du auf „Person blockieren“. Du siehst ihre Challenges und Kommentare dann nicht mehr und sie kann Deine Challenges weder annehmen noch kommentieren. Sie erfährt nicht den Grund. Unter „Dein Konto“ kannst Du die Blockierung wieder aufheben.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('KiezCoins baut auf gegenseitiges Vertrauen', 'KiezCoins baut auf gegenseitiges Vertrauen', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Kinder', 'Kinder', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Kinder dürfen die App nutzen, wenn Du sie als Elternteil oder Lehrkraft zu einer Gruppe hinzufügst. Du darfst Fotos Deiner Kinder posten, wenn sie sich damit wohlfühlen und damit einverstanden sind. Du darfst keine fremden Kinder ansprechen – besser Vorsicht als Nachsicht.', 'Kinder dürfen die App nutzen, wenn Du sie als Elternteil oder Lehrkraft zu einer Gruppe hinzufügst. Du darfst Fotos Deiner Kinder posten, wenn sie sich damit wohlfühlen und damit einverstanden sind. Du darfst keine fremden Kinder ansprechen – besser Vorsicht als Nachsicht.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Let’s have fun & do some good', 'Let’s have fun & do some good', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Physische und verbale Gewalt werden nicht toleriert, ebenso wenig Aufrufe zu und Verherrlichung jener. Challenges dürfen niemanden gefährden, nicht einmal Dich selbst.', 'Physische und verbale Gewalt werden nicht toleriert, ebenso wenig Aufrufe zu und Verherrlichung jener. Challenges dürfen niemanden gefährden, nicht einmal Dich selbst.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Private Daten anderer (Adresse, Klarname, Telefonnummer) dürfen niemals veröffentlicht werden. Fotos dürfen ausschließlich mit dem expliziten Einverständnis der Person veröffentlicht werden. Ein Nein beendet den Kontakt.', 'Private Daten anderer (Adresse, Klarname, Telefonnummer) dürfen niemals veröffentlicht werden. Fotos dürfen ausschließlich mit dem expliziten Einverständnis der Person veröffentlicht werden. Ein Nein beendet den Kontakt.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Rufe bei akuter Gefahr die Polizei unter 110 oder den Rettungsdienst unter 112.', 'Rufe bei akuter Gefahr die Polizei unter 110 oder den Rettungsdienst unter 112.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Stand 27.10.2026', 'Stand 27.10.2026', 'src/data/legal.ts (Rechtstexte)'),
  ('Tippe auf die Fahne an einer Challenge oder einem Kommentar oder auf „Person melden“ im Profil. Die gemeldete Person erfährt nicht, wer sie gemeldet hat. Beabsichtigte Falschmeldungen sind selbst ein Verstoß.', 'Tippe auf die Fahne an einer Challenge oder einem Kommentar oder auf „Person melden“ im Profil. Die gemeldete Person erfährt nicht, wer sie gemeldet hat. Beabsichtigte Falschmeldungen sind selbst ein Verstoß.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Wir begegnen allen Menschen mit Respekt: unabhängig von Herkunft, Hautfarbe, Religion, Geschlecht, sexueller Orientierung, geschlechtlicher Identität, Behinderung, Alter und sozialer Lage.', 'Wir begegnen allen Menschen mit Respekt: unabhängig von Herkunft, Hautfarbe, Religion, Geschlecht, sexueller Orientierung, geschlechtlicher Identität, Behinderung, Alter und sozialer Lage.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)'),
  ('Wir prüfen Meldungen zeitnah. Bei Verstößen entfernen wir Inhalte, verwarnen, beschränken oder sperren das Konto, bei schweren Verstößen sofort und dauerhaft. Straftaten zeigen wir an.', 'Wir prüfen Meldungen zeitnah. Bei Verstößen entfernen wir Inhalte, verwarnen, beschränken oder sperren das Konto, bei schweren Verstößen sofort und dauerhaft. Straftaten zeigen wir an.', 'src/data/legal.ts (Rechtstexte, Community-Regeln)')
